func parseTags(categories []Category) []string {
	var tags []string
	seen := make(map[string]bool) // 创建一个map来记录看到的标签

	for _, category := range categories {
		if category.Name == "海外美食" {
			continue
		}
		if !seen[category.Name] { // 如果标签还没有被添加到tags中
			seen[category.Name] = true // 标记为已见过
			tags = append(tags, category.Name)
		}
		if len(category.Children) > 0 {
			childTags := parseTags(category.Children)
			for _, tag := range childTags {
				if !seen[tag] { // 同样地，检查子标签是否已经添加
					seen[tag] = true // 标记为已见过
					tags = append(tags, tag)
				}
			}
		}
	}
	return tags
}

func (p *OpeDownload) processRow(ctx context.Context, l string, inHeadersShop []string) (string, error) {
	arr := strings.Split(l, "\t")
	if len(arr) != len(inHeadersShop) {
		return "", errors.New("header and line length not match")
	}
	row := make(map[string]string)
	for i := range inHeadersShop {
		row[inHeadersShop[i]] = arr[i]
	}
	v := ProductIndex{}
	row["shopinfo"] = strings.TrimSuffix(row["shopinfo"], "\n")
	row["shopinfo"] = strings.ReplaceAll(row["shopinfo"], "\\\\", "\\")
	err := json.Unmarshal([]byte(row["shopinfo"]), &v)
	if err != nil {
		return "", errors.New("shopinfo parse error:" + err.Error() + ", data:" + row["shopinfo"])
	}

	outLine := ""
	for i, name := range p.headers {
		value := ""
		// 替换字段名称
		if outHeaderTrans[name] != "" {
			name = outHeaderTrans[name]
		}

		// 解析读取的内容
		var shopInfo map[string]interface{}
		row["extra_info"] = strings.TrimSuffix(row["extra_info"], "\n")
		row["extra_info"] = strings.ReplaceAll(row["extra_info"], "\\\\", "\\")
		err := json.Unmarshal([]byte(row["extra_info"]), &shopInfo)
		if err != nil {
			log.Warn(ctx, "Error decoding err:%v, data:%v\n", err, row["extra_info"])
			return "", err
		}
		if v, ok := row[name]; ok {
			value = v
		} else if v, ok := shopInfo[name]; ok {
			if str, ok := v.(string); ok {
				value = str
			} else {
				valueBytes, _ := json.Marshal(v)
				value = string(valueBytes)
			}
		}
		if name == "std_tag" {
			var categories []Category
			if condition, ok := shopInfo["frontCate"]; ok {
				if strFrontCate, ok := condition.(string); ok {
					err = json.Unmarshal([]byte(strFrontCate), &categories)
					if err == nil {
						tags := parseTags(categories)
						if len(tags) > 1 {
							value = tags[1]
						}
					} else {
						log.Warn(ctx, "Error decoding err:%v, data:%v\n", err, strFrontCate)
					}
				}
			}

		}

		if _, ok := countFields[name]; !ok {
			countFields[name] = 0
		}
		if value == "" {
			countFields[name]++
		}

		// 构造输出
		value = strings.ReplaceAll(value, "\n", "")
		value = strings.ReplaceAll(value, "\t", "")
		if i != len(p.headers)-1 {
			outLine = outLine + value + "\t"
		} else {
			outLine = outLine + value + "\n"
		}
