var outHeaderTrans = map[string]string{
	"lat":          "latitude",
	"lng":          "longitude",
	"product_info": "shopinfo",
	"thirdid":      "tid",
}

var decodeHeaders = []string{"thirdid", "bid", "std_tag", "update_time", "shopUuid", "name", "businessStatus",
	"address", "poiTags", "frontImg", "avgPrice", "score", "rankInfos", "lat", "lng",
