type ShopInfo struct {
	ShopID         string        `json:"shopId"`
	ShopUUID       string        `json:"shopUuid"`
	Name           string        `json:"name"`
	BusinessStatus int           `json:"businessStatus"`
	FrontCate      string        `json:"frontCate"`
