func (p *OpeDownload) ErrNo() int32 {
	return operators.ERROR_DOWNLOAD
}

func parseTags(categories []Category) []string {
	var tags []string
	seen := make(map[string]bool) // 创建一个map来记录看到的标签

	for _, category := range categories {
		if category.Name == "海外美食" {
			continue
		}
		if !seen[category.Name] { // 如果标签还没有被添加到tags中
			seen[category.Name] = true // 标记为已见过
			tags = append(tags, category.Name)
		}
		if len(category.Children) > 0 {
			childTags := parseTags(category.Children)
			for _, tag := range childTags {
				if !seen[tag] { // 同样地，检查子标签是否已经添加
					seen[tag] = true // 标记为已见过
					tags = append(tags, tag)
				}
			}
		}
	}
	return tags
}

func (p *OpeDownload) processRow(ctx context.Context, l string, inHeadersShop []string) (string, error) {
	arr := strings.Split(l, "\t")
	if len(arr) != len(inHeadersShop) {
		return "", errors.New("header and line length not match")
	}
	row := make(map[string]string)
	for i := range inHeadersShop {
		row[inHeadersShop[i]] = arr[i]
	}
	v := ProductIndex{}
	row["shopinfo"] = strings.TrimSuffix(row["shopinfo"], "\n")
	row["shopinfo"] = strings.ReplaceAll(row["shopinfo"], "\\\\", "\\")
	err := json.Unmarshal([]byte(row["shopinfo"]), &v)
	if err != nil {
		return "", errors.New("shopinfo parse error:" + err.Error() + ", data:" + row["shopinfo"])
	}

	outLine := ""
	for i, name := range p.headers {
		value := ""
		// 替换字段名称
		if outHeaderTrans[name] != "" {
			name = outHeaderTrans[name]
		}

		// 解析读取的内容
		var shopInfo map[string]interface{}
		row["extra_info"] = strings.TrimSuffix(row["extra_info"], "\n")
		row["extra_info"] = strings.ReplaceAll(row["extra_info"], "\\\\", "\\")
		err := json.Unmarshal([]byte(row["extra_info"]), &shopInfo)
		if err != nil {
			log.Warn(ctx, "Error decoding err:%v, data:%v\n", err, row["extra_info"])
			return "", err
		}
		if v, ok := row[name]; ok {
			value = v
		} else if v, ok := shopInfo[name]; ok {
			if str, ok := v.(string); ok {
				value = str
			} else {
				valueBytes, _ := json.Marshal(v)
				value = string(valueBytes)
			}
		}
		if name == "std_tag" {
			var categories []Category
			if condition, ok := shopInfo["frontCate"]; ok {
				if strFrontCate, ok := condition.(string); ok {
					err = json.Unmarshal([]byte(strFrontCate), &categories)
					if err == nil {
						tags := parseTags(categories)
						if len(tags) > 1 {
							value = tags[1]
						}
					} else {
						log.Warn(ctx, "Error decoding err:%v, data:%v\n", err, strFrontCate)
					}
				}
			}

		}

		if _, ok := countFields[name]; !ok {
			countFields[name] = 0
		}
		if value == "" {
			countFields[name]++
		}

		// 构造输出
		value = strings.ReplaceAll(value, "\n", "")
		value = strings.ReplaceAll(value, "\t", "")
		if i != len(p.headers)-1 {
			outLine = outLine + value + "\t"
		} else {
			outLine = outLine + value + "\n"
		}
	}
	return outLine, nil
}

func (p *OpeDownload) DecodeFiles(ctx context.Context, dir string) error {
	// 读取shopinfo目录中的所有文件
	shopFiles, err := filepath.Glob(dir + "/shopinfo/*")
	if err != nil {
		return err
	}

	if len(shopFiles) == 0 {
		return fmt.Errorf("no shopinfo files found in directory %s/shopinfo", dir)
	}

	// 按文件名排序以确保一致性
	sort.Strings(shopFiles)

	// 输出文件
	fileSplitter := NewFileSplitter(10000, p.headers, dir+"/splits/shopinfo_decode") // 每10000条数据创建一个新文件
	defer fileSplitter.Close()                                                       // 确保在main结束时关闭文件
	outputFileErr, err := os.Create(dir + "/shopinfo_decode_err")
	if err != nil {
		return err
	}
	defer outputFileErr.Close()

	outputErrWriter := bufio.NewWriter(outputFileErr)
	var inHeadersShop []string
	headersRead := false

	// 处理所有shopinfo文件
	for _, shopFilePath := range shopFiles {
		shopFile, err := os.Open(shopFilePath)
		if err != nil {
			log.Warn(ctx, "Error opening file %s, err:%v", shopFilePath, err.Error())
			continue
		}

		// 创建逐行读取器
		shopScanner := bufio.NewReader(shopFile)

		// 读取标题行（只读取第一个文件的标题行）
		if !headersRead {
			if l, err := shopScanner.ReadString('\n'); err == nil {
				l = strings.TrimSuffix(l, "\n")
				inHeadersShop = strings.Split(l, "\t")
				headersRead = true
			} else {
				shopFile.Close()
				return fmt.Errorf("no header line found in file %s", shopFilePath)
			}
		} else {
			// 跳过后续文件的标题行
			_, err := shopScanner.ReadString('\n')
			if err != nil {
				shopFile.Close()
				log.Warn(ctx, "Error reading header from file %s, err:%v", shopFilePath, err.Error())
				continue
			}
		}

		for {
			l, err := shopScanner.ReadString('\n')
			if err != nil {
				break
			}
			outLine, err := p.processRow(ctx, l, inHeadersShop)
			if err != nil {
				log.Notice(ctx, "Error processing row: %v, err:%v", l, err.Error())
				_, err = outputErrWriter.WriteString(l)
				if err != nil {
					shopFile.Close()
					log.Warn(ctx, "Error writing to output_file_err, err:%s", err.Error())
					return err
				}
			}

			err = fileSplitter.WriteString(outLine)
			if err != nil {
				shopFile.Close()
				log.Warn(ctx, "Error writing to output file, err:%s", err.Error())
				return err
			}
		}
		shopFile.Close()
	}

	return nil
}

func (p *OpeDownload) Download(ctx context.Context, batchInput *operators.BatchInput, dir string) error {
	// 检查是否已经有数据文件
	productInfoDir := dir + "/productinfo"
	shopInfoDir := dir + "/shopinfo"

	// 检查是否已经有足够的文件存在
	_, err := os.Stat(productInfoDir)
	_, err2 := os.Stat(shopInfoDir)
	if err == nil && err2 == nil {
		// 检查目录是否为空
		productFiles, _ := filepath.Glob(productInfoDir + "/*")
		shopFiles, _ := filepath.Glob(shopInfoDir + "/*")
		if len(productFiles) > 0 && len(shopFiles) > 0 {
			log.Notice(ctx, "Data files already exist in %s", dir)
			return nil
		}
	}

	// 确保父目录存在
	err = os.MkdirAll(dir, os.ModePerm)
	if err != nil {
		log.Warn(ctx, "Error creating directory %s, err:%v", dir, err.Error())
		return err
	}

	// 关键：先创建目标目录，然后才能AFS下载
	os.MkdirAll(productInfoDir, os.ModePerm)
	os.MkdirAll(shopInfoDir, os.ModePerm)

	afsClient := file.AfsClient{
		CmdPrefix: afsPrefix,
		UserName:  "poi-engine",
		Password:  "poi-engine-online",
	}

	// Download product info files - 直接下载到目标目录
	afspath := "afs://aries.afs.baidu.com:9902/user/aiad_chuilei/meishi/cater_product_info_export/" +
		batchInput.GetDateBefore()
	log.Notice(ctx, "Downloading from %s to %s", afspath, productInfoDir)
	err = afsClient.Get(afspath, productInfoDir)
	if err != nil {
		log.Warn(ctx, "Error download productinfo directory, err:%v", err.Error())
		return err
	}

	// Download shop info files - 直接下载到目标目录
	shopAfspath := "afs://aries.afs.baidu.com:9902/user/aiad_chuilei/meishi/shop_product_index_export/" +
		batchInput.GetDateBefore()
	log.Notice(ctx, "Downloading from %s to %s", shopAfspath, shopInfoDir)
	err = afsClient.Get(shopAfspath, shopInfoDir)
	if err != nil {
		log.Warn(ctx, "Error download shopinfo directory, err:%v", err.Error())
		return err
	}

	return nil
}

/*
* Run - the entry of dowload.
*
* PARAMS:
*   - ctx: the context
*	- input: input params
*	- output: output struct, used in inner process
*
* RETURNS:
*   - output: output struct, used in inner process
*	- error
 */
func (p *OpeDownload) Run(ctx context.Context, input interface{}, output interface{}) error {
	log.Notice(ctx, "begin to run OpeDownload")
	batchInput, ok := input.(*operators.BatchInput)
	if !ok {
		return errors.New("convert input to BatchInput fail")
	}
	dir := batchInput.Cwd + "/data/" + batchInput.Date + "/meituan"
	err := os.MkdirAll(dir, os.ModePerm)
	if err != nil {
		return err
	}
	err = os.RemoveAll(dir + "/splits")
	if err != nil {
		return err
	}
	err = os.MkdirAll(dir+"/splits", os.ModePerm)
	if err != nil {
		return err
	}
	log.Notice(ctx, "begin to download files")
	// check wheter data is ready

	for retry := 3; retry > 0; retry-- {
		err = p.Download(ctx, batchInput, dir)
		if err == nil {
			break
		}
		log.Notice(ctx, "data is not ready")
		time.Sleep(5 * time.Minute)
	}
	if err != nil {
		return err
	}

	// decode files
	log.Notice(ctx, "DownloadFiles completely! begin to decode")
	p.headers = decodeHeaders
	err = p.DecodeFiles(ctx, dir)
	if err != nil {
		return err
	}
	log.Notice(ctx, "decode completely! count fields:%v", countFields)
	return nil
}

